        arrayOf("Tour;Terrain;Équipe/Joueur A;Score A;Équipe/Joueur B;Score B;Joueurs en attente", "Round;Court;Team/Player A;Score A;Team/Player B;Score B;Players waiting", "Ronda;Pista;Equipo/Jugador A;Resultado A;Equipo/Jugador B;Resultado B;Jugadores en espera", "Turno;Campo;Squadra/Giocatore A;Punteggio A;Squadra/Giocatore B;Punteggio B;Giocatori in attesa", "Ronda;Campo;Equipa/Jogador A;Resultado A;Equipa/Jogador B;Resultado B;Jogadores em espera", "Runde;Platz;Team/Spieler A;Ergebnis A;Team/Spieler B;Ergebnis B;Wartende Spieler", "轮次；球场；队伍/球员 A；比分 A；队伍/球员 B；比分 B；等待球员", "ラウンド；コート；チーム/プレーヤー A；スコア A；チーム/プレーヤー B；スコア B；待機中", "राउंड; कोर्ट; टीम/खिलाड़ी A; स्कोर A; टीम/खिलाड़ी B; स्कोर B; प्रतीक्षा कर रहे खिलाड़ी", "Ronde;Baan;Team/Speler A;Score A;Team/Speler B;Score B;Wachtende spelers", "Раунд;Корт;Команда/игрок A;Счёт A;Команда/игрок B;Счёт B;Ожидающие игроки", "Kolo;Kurt;Tým/Hráč A;Skóre A;Tým/Hráč B;Skóre B;Čekající hráči", "Runda;Teren;Tim/Igrač A;Rezultat A;Tim/Igrač B;Rezultat B;Igrači na čekanju"),
        arrayOf("Bilan du tournoi de tennis", "Tennis tournament report", "Informe del torneo de tenis", "Resoconto del torneo di tennis", "Relatório do torneio de ténis", "Tennis-Turnierbericht", "网球锦标赛报告", "テニストーナメントレポート", "टेनिस टूर्नामेंट रिपोर्ट", "Tennistoernooi-verslag", "Отчёт о теннисном турнире", "Zpráva o tenisovém turnaji", "Izveštaj teniskog turnira"),
